{
  "schemaVersion": 1,
  "baselineVersion": "1.7.2",
  "policy": {
    "versioning": "semver",
    "breakingChangesRequireMajor": true,
    "minimumDeprecationMinorReleases": 2,
    "minimumDeprecationDays": 90,
    "dateBasis": "UTC calendar dates"
  },
  "releases": [],
  "deprecations": [
    {
      "id": "segmented-role-override",
      "contract": "SegmentedControl.role DOM override and inherited role prop",
      "replacement": "Use mode=\"radio\" for value selection or mode=\"tabs\" for caller-rendered panels; mode owns root and item roles.",
      "announcedVersion": null,
      "announcedAt": null
    }
  ],
  "pendingChanges": [
    {
      "id": "compiled-default-entry",
      "kind": "breaking",
      "description": "The default package entry changes from raw JSX to compiled ESM; explicit source entry remains available."
    },
    {
      "id": "apg-menu-keyboard",
      "kind": "breaking",
      "description": "Menu adopts the approved APG arrow-key and Tab-closes interaction contract."
    },
    {
      "id": "floating-default-portal",
      "kind": "breaking",
      "description": "Floating panels use body placement by default, with explicit inline opt-out and automatic native form/fieldset fallback."
    },
    {
      "id": "segmented-radio-default",
      "kind": "breaking",
      "description": "SegmentedControl defaults to radiogroup semantics for value selection; caller-rendered panels use explicit tabs mode."
    },
    {
      "id": "remove-segmented-role-override",
      "kind": "removal",
      "description": "SegmentedControl mode owns ARIA roles and the inherited caller role override is removed. Notice has not been published.",
      "deprecationId": "segmented-role-override"
    }
  ]
}
